C++ Built-in Functions — Complete Cheat Sheet for OA
1. Type Conversion

cpp
// int to string
int n = 42;
string s = to_string(n);        // "42"

// string to int
string s = "42";
int n = stoi(s);                // 42

// string to long long
long long n = stoll(s);         // 42LL

// string to float/double
float f  = stof(s);             // 42.0f
double d = stod(s);             // 42.0

// char to int (digit)
char c = '7';
int n = c - '0';                // 7

// int to char (digit)
int n = 7;
char c = n + '0';               // '7'

// char to uppercase / lowercase
char upper = toupper('a');      // 'A'
char lower = tolower('A');      // 'a'

// check char type
isdigit('5');   // true
isalpha('a');   // true
isalnum('a');   // true  (letter or digit)
isspace(' ');   // true

isupper('A');   // true
islower('a');   // true
2. Vector Operations

cpp
vector<int> v = {3, 1, 4, 1, 5};

v.push_back(9);         // add to end
v.pop_back();           // remove from end
v.size();               // number of elements
v.empty();              // true if size == 0
v.front();              // first element
v.back();               // last element
v.clear();              // remove all elements
v.resize(10);           // resize to 10 (fills 0)
v.resize(10, -1);       // resize to 10 (fills -1)
v.insert(v.begin()+2, 99);   // insert 99 at index 2
v.erase(v.begin()+2);        // erase element at index 2
v.erase(v.begin(), v.begin()+3); // erase first 3 elements

// 2D vector
vector<vector<int>> dp(n, vector<int>(m, 0));

// initialise vector of size n with value -1
vector<int> dp(n, -1);
3. Sorting

cpp
vector<int> v = {3, 1, 4, 1, 5};

// ascending
sort(v.begin(), v.end());

// descending
sort(v.begin(), v.end(), greater<int>());

// custom comparator — sort by second element of pair
vector<pair<int,int>> p = {{1,3},{2,1},{3,2}};
sort(p.begin(), p.end(), [](auto& a, auto& b){
    return a.second < b.second;
});

// sort string
string s = "dcba";
sort(s.begin(), s.end());    // "abcd"

// partial sort — only sort first k elements
partial_sort(v.begin(), v.begin()+3, v.end());

// check if sorted
is_sorted(v.begin(), v.end());   // true or false
4. Min / Max Operations

cpp
// between two values
min(3, 5);              // 3
max(3, 5);              // 5
min({3, 1, 4, 1, 5});  // 1 — among multiple values
max({3, 1, 4, 1, 5});  // 5

// in array/vector
*min_element(v.begin(), v.end());   // minimum value
*max_element(v.begin(), v.end());   // maximum value

// index of min/max
int idx = min_element(v.begin(), v.end()) - v.begin();
int idx = max_element(v.begin(), v.end()) - v.begin();

// clamp — keep value within range
clamp(x, lo, hi);   // if x<lo return lo, if x>hi return hi
5. String Operations

cpp
string s = "hello world";

s.length();              // 11
s.size();                // 11 (same as length)
s.empty();               // false
s.substr(6, 5);          // "world" (start, length)
s.find("world");         // 6 (index) or string::npos if not found
s.rfind("l");            // last occurrence index
s.replace(6, 5, "C++");  // "hello C++"
s.erase(5, 6);           // "hello"
s.insert(5, " there");   // "hello there world"
s.append(" again");      // adds to end
s += " again";           // same as append
s.compare("hello");      // 0 if equal
reverse(s.begin(), s.end());  // reverse string

// split string by delimiter (no built-in, use this)
vector<string> split(string s, char delim) {
    vector<string> res;
    stringstream ss(s);
    string token;
    while(getline(ss, token, delim)) {
        res.push_back(token);
    }
    return res;
}

// check if substring exists
if(s.find("world") != string::npos) { ... }

// convert all to lowercase/uppercase
transform(s.begin(), s.end(), s.begin(), ::tolower);

transform(s.begin(), s.end(), s.begin(), ::toupper);

// count occurrences of char in string
count(s.begin(), s.end(), 'l');   // 3
6. Math Functions

cpp
#include <cmath>

abs(-5);          // 5       (int)
fabs(-5.5);       // 5.5     (float/double)
sqrt(16);         // 4.0
pow(2, 10);       // 1024.0
ceil(4.2);        // 5.0
floor(4.9);       // 4.0
round(4.5);       // 5.0
log(x);           // natural log
log2(x);          // log base 2
log10(x);         // log base 10

// GCD and LCM
__gcd(12, 8);                   // 4
int lcm = (a / __gcd(a,b)) * b; // LCM formula

// Integer limits
INT_MAX    // 2147483647
INT_MIN    // -2147483648
LLONG_MAX  // 9223372036854775807
LLONG_MIN  // -9223372036854775808
DBL_MAX    // max double
7. HashMap (unordered_map)

cpp
unordered_map<string, int> mp;

mp["apple"] = 5;           // insert/update
mp.count("apple");         // 1 if exists, 0 if not
mp.find("apple");          // iterator, mp.end() if not found
mp.erase("apple");         // delete key
mp.size();                 // number of keys
mp.empty();                // true if empty

// iterate
for(auto& [key, val] : mp) {
    cout << key << " " << val << "\n";
}

// frequency count pattern (most used in GS)
unordered_map<int, int> freq;
for(int x : v) freq[x]++;
8. Set and Multiset

cpp
set<int> s;
s.insert(5);
s.erase(5);
s.count(5);           // 1 if present, 0 if not
s.find(5);            // iterator
s.size();
s.empty();
*s.begin();           // smallest element
*s.rbegin();          // largest element
s.lower_bound(5);     // iterator to first element >= 5
s.upper_bound(5);     // iterator to first element > 5

// multiset — allows duplicates
multiset<int> ms;
ms.insert(5);
ms.insert(5);         // now has two 5s
ms.erase(ms.find(5)); // removes only ONE 5
9. Stack and Queue

cpp
// Stack (LIFO)
stack<int> st;
st.push(5);
st.pop();
st.top();
st.empty();
st.size();

// Queue (FIFO)
queue<int> q;
q.push(5);
q.pop();
q.front();
q.back();
q.empty();
q.size();

// Deque (both ends)
deque<int> dq;
dq.push_front(1);
dq.push_back(2);
dq.pop_front();
dq.pop_back();
dq.front();
dq.back();

// Priority Queue (max heap by default)
priority_queue<int> pq;
pq.push(5);
pq.top();        // largest element
pq.pop();


// Min heap
priority_queue<int, vector<int>, greater<int>> minpq;
minpq.push(5);
minpq.top();     // smallest element
10. Binary Search

cpp
// array must be sorted first
vector<int> v = {1, 3, 5, 7, 9};

// returns true/false
binary_search(v.begin(), v.end(), 5);   // true

// returns iterator to first element >= target
auto it = lower_bound(v.begin(), v.end(), 5);
int idx = it - v.begin();               // index

// returns iterator to first element > target
auto it = upper_bound(v.begin(), v.end(), 5);
int idx = it - v.begin();               // index

// count occurrences in sorted array
int cnt = upper_bound(v.begin(),v.end(),5)
        - lower_bound(v.begin(),v.end(),5);
11. Algorithm Functions

cpp
// reverse
reverse(v.begin(), v.end());

// fill array with value
fill(v.begin(), v.end(), 0);

// count occurrences
count(v.begin(), v.end(), 5);

// accumulate (sum)
#include <numeric>
int sum = accumulate(v.begin(), v.end(), 0);

// next permutation / prev permutation
next_permutation(v.begin(), v.end());
prev_permutation(v.begin(), v.end());

// rotate
rotate(v.begin(), v.begin()+2, v.end());
// moves element at index 2 to front

// unique — removes consecutive duplicates
// (sort first, then unique)
sort(v.begin(), v.end());
v.erase(unique(v.begin(), v.end()), v.end());

// copy
vector<int> v2(v.size());
copy(v.begin(), v.end(), v2.begin());
12. Pairs and Tuples

cpp
// pair
pair<int,int> p = {1, 2};
p.first;     // 1
p.second;    // 2
make_pair(1, 2);

// tuple
tuple<int,int,string> t = {1, 2, "hello"};
get<0>(t);   // 1
get<1>(t);   // 2
get<2>(t);   // "hello"
make_tuple(1, 2, "hello");
13. Bit Manipulation (GS Loves These)

cpp
// check if bit i is set
(n >> i) & 1

// set bit i
n | (1 << i)

// clear bit i
n & ~(1 << i)

// toggle bit i
n ^ (1 << i)

// count set bits
__builtin_popcount(n);    // for int
__builtin_popcountll(n);  // for long long

// check if power of 2
(n & (n-1)) == 0

// lowest set bit
n & (-n)

// XOR trick — find element appearing once
int result = 0;
for(int x : v) result ^= x;
14. Common Patterns in One Line

cpp
// swap two variables
swap(a, b);

// check if number is even/odd
n % 2 == 0    // even
n & 1         // odd (faster)

// absolute difference
abs(a - b);

// infinity values for DP
int INF = 1e9;
int NEG_INF = -1e9;

// mod operation (Goldman Sachs often asks mod 1e9+7)
const int MOD = 1e9 + 7;
result = (result + x) % MOD;
result = (result * x) % MOD;

// fast input output (use at top of main for large input)
ios_base::sync_with_stdio(false);
cin.tie(NULL);
Most Important for Goldman Sachs Specifically

Priority 1 — Use these in almost every problem:
  sort, unordered_map, min/max, abs
  vector operations, string operations

Priority 2 — Use in medium problems:
  priority_queue (min/max heap)
  lower_bound / upper_bound
  set / multiset
  accumulate, count

Priority 3 — Use in hard problems:
  __builtin_popcount (bit problems)
  next_permutation (combinatorics)
  __gcd (math problems)
  rotate, unique

Save this as a reference file and review it the night before your OA.

Here's a clean O(N log N) solution:


cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    int T;
    scanf("%d", &T);
    while (T--) {
        int N, K;
        scanf("%d %d", &N, &K);
        vector<long long> W(N);
        for (auto &w : W) scanf("%lld", &w);

        sort(W.begin(), W.end());

        // prefix sums
        vector<long long> prefix(N + 1, 0);
        for (int i = 0; i < N; i++) prefix[i + 1] = prefix[i] + W[i];
        long long total = prefix[N];

        auto sumSmallest = [&](int cnt) { return prefix[cnt]; };
        auto sumLargest  = [&](int cnt) { return total - prefix[N - cnt]; };

        // Option 1: batch of size K = smallest K, other = largest (N-K)
        long long diff1 = sumLargest(N - K) - sumSmallest(K);

        // Option 2: batch of size K = largest K, other = smallest (N-K)
        long long diff2 = sumLargest(K) - sumSmallest(N - K);

        long long ans = max(diff1, diff2);
        printf("%lld\n", ans);
    }
    return 0;

}

Logic:

Total sum S is fixed. If one batch (size K) has sum s1, the other has S - s1, and the difference is |2·s1 − S|.
To maximize this, push s1 to an extreme: make the K-batch either the K smallest weights or the K largest weights.
Compute both resulting differences and take the max — since K ≠ N−K in general, these two extremes aren't symmetric, so both must be checked.
Using sorted array + prefix sums makes sum of smallest/largest cnt elements an O(1) lookup.

Complexity: O(N log N) per test case (dominated by sorting), well within limits for N ≤ 100, T ≤ 100.

This is the classic "K-th largest element in a stream" problem — maintain a min-heap of size K.

Approach: For each incoming score, push it into a min-heap capped at size K (pop the smallest whenever size exceeds K). Once the heap has K elements, its top (minimum of the heap) is exactly the K-th highest score seen so far. Before that, output -1.


cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    int T;
    scanf("%d", &T);
    while (T--) {
        int K, N;
        scanf("%d %d", &K, &N);

        vector<long long> A(N);
        for (auto &x : A) scanf("%lld", &x);

        // min-heap holding the K largest elements seen so far
        priority_queue<long long, vector<long long>, greater<long long>> minHeap;

        vector<long long> ans(N);

        for (int i = 0; i < N; i++) {
            long long val = A[i];

            if ((int)minHeap.size() < K) {
                minHeap.push(val);
            } else if (val > minHeap.top()) {
                minHeap.pop();
                minHeap.push(val);
            }
            // if val <= minHeap.top() and heap already full, it can't be in top-K, ignore

            if ((int)minHeap.size() < K) {
                ans[i] = -1;
            } else {

                ans[i] = minHeap.top();
            }
        }

        for (int i = 0; i < N; i++) {
            printf("%lld%c", ans[i], (i + 1 == N) ? '\n' : ' ');
        }
    }
    return 0;
}

Why this works:

The min-heap always holds (up to) the K largest elements seen so far.
Its smallest element (the top) is therefore the K-th largest overall.
Every new value either grows the heap (while size < K) or, if it beats the current K-th largest, replaces it (pop smallest, push new). Otherwise it's correctly discarded since it can't be in the top K.

Complexity: O(N log K) per test stream, O(1) extra query time per event — efficient even for large N.

One note: I couldn't fully confirm the constraints section (N, K, A_i bounds) since it may be below the photographed area — I used long long to be safe against large values. Let me know the actual constraints if they differ and I can tighten/adjust the solution (e.g., switch to int for speed, or handle very large N/T with faster I/O).
